import string

def tr_lower(s: str) -> str:
    """Türkçe kurallarına uygun olarak metni küçük harfe çevirir."""
    mapping = {
        'İ': 'i',
        'I': 'ı',
        'Ş': 'ş',
        'Ğ': 'ğ',
        'Ü': 'ü',
        'Ö': 'ö',
        'Ç': 'ç',
    }
    res = []
    for char in s:
        if char in mapping:
            res.append(mapping[char])
        else:
            res.append(char.lower())
    return "".join(res)

