        'ş': 'Ş',
        'ğ': 'Ğ',
        'ü': 'Ü',
        'ö': 'Ö',
        'ç': 'Ç',
    }
    res = []
    for char in s:
        if char in mapping:
            res.append(mapping[char])
        else:
            res.append(char.upper())
    return "".join(res)

def tr_sorted(words: list[str]) -> list[str]:
    """Kelimeleri Türk alfabesine göre (büyük/küçük harf duyarsız) sıralar."""
    tr_alphabet = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
